// One item per STL. Design name comes from the file's own folder, which is
// how the supplier identifies a piece — the STL filename itself is
// inconsistent ("64-STL", "7 INCH RPT", "52-CAD-7INCH") and would produce
// model files nobody could map back to a design.
const stdout = $input.first().json.stdout || '';
const settings = $('Settings').first().json;

const items = [];
for (const line of stdout.split(/\r?\n/)) {
  const t = line.trim();
  if (!t) continue;
  let row;
  try { row = JSON.parse(t); } catch { continue; }
  if (!row?.path) continue;

  const parts = row.path.split(/[\\/]/);
  // .../<design>/<design>/<file>.stl — walk back to the first folder whose
  // name is not simply repeated, which is the design id.
  const design = parts[parts.length - 2] || row.name;
  const slug = String(design).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

  items.push({
    json: {
      ...row,
      design,
      out: `${settings.modelDir}\\design-${slug}.glb`,
      slug: `design-${slug}`,
    },
  });
}

if (!items.length) throw new Error('No .stl found under workDir — did extraction succeed?');

return items;

// Every converted model, plus the config block to paste into tryon.php.
const ok = [];
const failed = [];

for (const item of $input.all()) {
  const out = (item.json.stdout || '').trim();
  if (item.json.exitCode && item.json.exitCode !== 0) {
    failed.push({ error: item.json.stderr || 'non-zero exit' });
    continue;
  }
  try {
    ok.push(JSON.parse(out.split(/\r?\n/).pop()));
  } catch {
    failed.push({ error: out.slice(0, 300) || item.json.stderr || 'no JSON on stdout' });
  }
}

// A converted model is NOT wearable on its own: the mesh may be a flat
// manufacturing layout rather than worn shape, and its hole may lie on any
// axis. Both are judgement calls, so emit a starting point rather than
// pretending the pipeline can decide.
const snippets = ok.map((r) => {
  const [x, y, z] = r.dimensionsMm;
  const thin = Math.min(x, y, z);
  // The hole runs along whichever axis is thinnest for a flat bangle; the
  // stage wants it along +Y.
  const rotation = thin === z ? '[-90, 0, 0]' : thin === x ? '[0, 0, 90]' : '[0, 0, 0]';

  return [
    `// ${r.input} — ${r.dimensionsMm.join(' x ')} mm, ${r.trianglesOut.toLocaleString()} tris`,
    `'<product-slug>' => [`,
    `    'mode' => 'wrist',   // or 'finger'`,
    `    'render' => '3d',`,
    `    'model' => '/models/tryon/${r.output}',`,
    `    'model_rotation' => ${rotation},`,
    `    'scale' => 1.15,`,
    `],`,
  ].join('\n');
});

return [{
  json: {
    converted: ok.length,
    failed: failed.length,
    totalMB: Number((ok.reduce((s, r) => s + r.bytes, 0) / 1048576).toFixed(2)),
    models: ok,
    failures: failed,
    configSnippets: snippets.join('\n\n'),
    note: 'Check each model is in WORN shape, not a flat manufacturing layout, and confirm the design maps to a real catalogue SKU before enabling it.',
  },
}];
